package org.usbworkbench;
import android.content.*;import android.content.pm.*;import java.io.*;import java.util.*;
public final class ExtraFormatTest{
 static int checks;static void check(boolean b,String s){checks++;if(!b)throw new AssertionError(s);}
 public static void main(String[] args)throws Exception{File dir=new File("artifacts/extra-format-fixtures");dir.mkdirs();Context c=new Context(){public ApplicationInfo getApplicationInfo(){ApplicationInfo i=new ApplicationInfo();i.nativeLibraryDir=new File("app/src/main/jniLibs/"+(args.length==0?"arm64-v8a":args[0])).getAbsolutePath();return i;}public File getFilesDir(){return dir;}};
 for(String table:new String[]{"mbr","gpt"}){File path=new File(dir,"udf-"+table+".img");try(NativeIntegrationTest.Image d=new NativeIntegrationTest.Image(path,64L*1048576)){List<String> stages=new ArrayList<>();NativeFormat.format(c,d,"udf",table,"USBWORK",0,(a,b)->{},()->false,stages::add);check(stages.contains("udf_metadata"),"stage");ExtraFormat.verifyUdf(new SliceDevice(d,2048,d.blockCount()-2048-(table.equals("gpt")?33:0)));check(true,"UDF anchors CRC");check(UsbAnalyzer.render(new UsbAnalyzer(d,(a,b)->{}).analyze(),false).contains("UDF"),"actual UDF analyzer recognition");if(table.equals("gpt"))check(AdvancedDiskTools.inspectGpt(d).contains("CRC OK"),"GPT");else{byte[] mbr=new byte[512];d.read(0,mbr,512);check(mbr[450]==7&&mbr[510]==0x55,"MBR");}System.out.println("PASS actual UDF / "+table);}finally{path.delete();}}
 for(String fs:new String[]{"apfs","hfsplus","btrfs","xfs"}){File f=new File(dir,fs+".img");try(NativeIntegrationTest.Image d=new NativeIntegrationTest.Image(f,(fs.equals("xfs")?512L:256L)*1048576)){NativeFormat.format(c,d,fs,"gpt","USBWORK",0,(a,b)->{},()->false);check(AdvancedDiskTools.inspectGpt(d).contains("CRC OK"),fs+" GPT");if(fs.equals("apfs"))ExtraFormat.verifyApfs(new SliceDevice(d,2048,(d.blockCount()-2048-33)/8*8));else if(fs.equals("btrfs"))ExtraFormat.verifyBtrfs(new SliceDevice(d,2048,(d.blockCount()-2048-33)/8*8));else if(fs.equals("xfs"))ExtraFormat.verifyXfs(new SliceDevice(d,2048,(d.blockCount()-2048-33)/8*8));else ExtraFormat.verifyHfs(new SliceDevice(d,2048,(d.blockCount()-2048-33)/8*8));check(true,fs+" metadata");System.out.println("PASS actual "+fs+" / GPT");}finally{f.delete();}}
 for(String label:new String[]{"","   ","bad/name","bad:name","too-long-123456789","عربي"}){File f=new File(dir,"invalid.img");try(NativeIntegrationTest.Image d=new NativeIntegrationTest.Image(f,64L*1048576)){try{NativeFormat.format(c,d,"udf","mbr",label,0,(a,b)->{},()->false);throw new AssertionError("accepted");}catch(IOException e){check(e.getMessage().equals("EXTRA_FORMAT_LABEL"),"labelguard");}check(d.writes==0,"zero writes");}finally{f.delete();}}
 File bad=new File(dir,"xfs-label.img");try(NativeIntegrationTest.Image d=new NativeIntegrationTest.Image(bad,512L*1048576)){try{NativeFormat.format(c,d,"xfs","gpt","1234567890123",0,(a,b)->{},()->false);throw new AssertionError("XFS long label accepted");}catch(IOException e){check(e.getMessage().equals("EXTRA_FORMAT_LABEL"),"XFS label before writes");}check(d.writes==0,"XFS long label zero writes");}finally{bad.delete();}
 System.out.println("PASS: "+checks+" extra formatter/read-only checker/metadata/table/invalid-label checks");}}
